-- West Wing page: topic and seed facts. Generated by build.py; do not edit by hand.
insert into public.topics (slug, title, description, suggested_by)
values ('west-wing', 'The West Wing: good calls and bad calls', 'The political decisions in The West Wing, by the character who made each one, season 1 to season 2 episode 17. Readers rate each as a good call, mixed or a bad call.', 'seed')
on conflict (slug) do nothing;

insert into public.facts (topic, text, sources, tags, suggested_by, created_at)
select v.topic, v.text, v.sources, v.tags, 'seed', now() + v.n * interval '1 millisecond'
from (values
  (0, 'west-wing', 'On a TV political show, Josh tells a Christian-right spokeswoman that the God she prays to is too busy being indicted for tax fraud. (S1E1, "Pilot")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', '1999-09-22', 'season-1']::text[]),
  (1, 'west-wing', 'To save Josh''s job, Toby sets up a peace meeting at the White House with the Christian-right leaders Josh insulted. (S1E1, "Pilot")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['toby', '1999-09-22', 'season-1']::text[]),
  (2, 'west-wing', 'Bartlet offers the Christian-right leaders nothing for Josh''s insult. He tells them to denounce an extremist group that sent his granddaughter a threat, and orders them out of the White House. (S1E1, "Pilot")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '1999-09-22', 'season-1']::text[]),
  (3, 'west-wing', 'Hoynes hedges in public on the President''s bill, then brushes off the press secretary when she raises it with him. (S1E2, "Post Hoc, Ergo Propter Hoc")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['hoynes', '1999-09-29', 'season-1']::text[]),
  (4, 'west-wing', 'Sam keeps seeing Laurie, a law student who works as a call girl, after his colleagues warn him what the story would do to the White House. (S1E2, "Post Hoc, Ergo Propter Hoc")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['sam', '1999-09-29', 'season-1']::text[]),
  (5, 'west-wing', 'After Syria shoots down a US military plane, Bartlet demands a far heavier strike, including bombing an airport. He ends by approving the Joint Chiefs'' smaller, proportional strike. (S1E3, "A Proportional Response")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '1999-10-06', 'season-1']::text[]),
  (6, 'west-wing', 'After the strike on Syria, Leo tells the President to his face that piling up the body count will deter no one, and that if he wants to rule by force he will have to get past Leo first. (S1E3, "A Proportional Response")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['leo', '1999-10-06', 'season-1']::text[]),
  (7, 'west-wing', 'C.J. tells reporter Danny Concannon there is no story in Sam''s friendship with a call girl, and that she will defend Sam. Danny, who has too little to print, backs off for now. (S1E3, "A Proportional Response")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['cj', '1999-10-06', 'season-1']::text[]),
  (8, 'west-wing', 'Josh wins back a vote for the gun bill by threatening a Democratic congressman with a primary challenger backed by the President. (S1E4, "Five Votes Down")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', '1999-10-13', 'season-1']::text[]),
  (9, 'west-wing', 'Hoynes wins the last vote the White House needs for its gun bill, and asks the congressman to tell the other holdouts about their talk. (S1E4, "Five Votes Down")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['hoynes', '1999-10-13', 'season-1']::text[]),
  (10, 'west-wing', 'Leo makes the senior staff spend a day meeting fringe groups who normally cannot get a hearing at the White House. (S1E5, "The Crackpots and These Women")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['leo', '1999-10-20', 'season-1']::text[]),
  (11, 'west-wing', 'Josh hands back the card that would take him to safety in a nuclear attack, because his colleagues do not get one. (S1E5, "The Crackpots and These Women")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', '1999-10-20', 'season-1']::text[]),
  (12, 'west-wing', 'Toby and Mandy argue the case for census sampling directly to three wavering congressmen. One of them, Mr. Willis, changes his vote because the argument persuaded him. (S1E6, "Mr. Willis of Ohio")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['toby', '1999-11-03', 'season-1']::text[]),
  (13, 'west-wing', 'In an armed standoff with survivalists in Idaho, Bartlet takes Mandy''s advice and sends in a negotiator before letting the FBI raid. The negotiator is shot. (S1E7, "The State Dinner")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '1999-11-10', 'season-1']::text[]),
  (14, 'west-wing', 'Bartlet tells the truckers'' union and management that he will nationalize the trucking industry and draft the truckers into the military unless they settle that night. (S1E7, "The State Dinner")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '1999-11-10', 'season-1']::text[]),
  (15, 'west-wing', 'Toby insists on a state-dinner toast that criticises Indonesia''s political repression. He and Josh then ask an Indonesian official to free a French political prisoner, and get nowhere, partly because of the toast. (S1E7, "The State Dinner")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['toby', '1999-11-10', 'season-1']::text[]),
  (16, 'west-wing', 'Bartlet rebukes his Vice President in front of the whole Cabinet. Word reaches a reporter, and C.J. trades him an exclusive interview to keep it out of print. (S1E8, "Enemies")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '1999-11-17', 'season-1']::text[]),
  (17, 'west-wing', 'A banking bill the President wants comes with a strip-mining rider attached. Josh''s answer: sign the bill, then use the Antiquities Act to make the land a national park. (S1E8, "Enemies")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', '1999-11-17', 'season-1']::text[]),
  (18, 'west-wing', 'Bartlet drops his safe, vetted Supreme Court pick after the judge says the Constitution holds no general right to privacy. He nominates Roberto Mendoza, a harder confirmation. (S1E9, "The Short List")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '1999-11-24', 'season-1']::text[]),
  (19, 'west-wing', 'Toby uses the President''s name to arrange a military funeral with an honour guard for a homeless Korean War veteran he never met. (S1E10, "In Excelsis Deo")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['toby', '1999-12-15', 'season-1']::text[]),
  (20, 'west-wing', 'Against Leo''s wishes, Josh and Sam ask Laurie for compromising information about Republican clients, to use against the congressman going after Leo. (S1E10, "In Excelsis Deo")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', 'sam', '1999-12-15', 'season-1']::text[]),
  (21, 'west-wing', 'After a gay teenager is beaten to death, C.J. talks up hate-crimes legislation at her briefings, and keeps pushing after Sam and Leo tell her to dial it down. (S1E10, "In Excelsis Deo")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['cj', '1999-12-15', 'season-1']::text[]),
  (22, 'west-wing', 'With India and Pakistan close to war, Bartlet sends for Lord John Marbury, an eccentric British expert, over Leo''s objection. (S1E11, "Lord John Marbury")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-01-05', 'season-1']::text[]),
  (23, 'west-wing', 'Leo keeps C.J. out of the briefing on Indian troop movements, so she unknowingly waves off a reporter''s accurate question. (S1E11, "Lord John Marbury")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['leo', '2000-01-05', 'season-1']::text[]),
  (24, 'west-wing', 'Leo faces the press and admits his past treatment for alcohol and Valium addiction. (S1E12, "He Shall, from Time to Time...")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['leo', '2000-01-12', 'season-1']::text[]),
  (25, 'west-wing', 'Bartlet has kept his multiple sclerosis from the public and, until now, from his own chief of staff. (S1E12, "He Shall, from Time to Time...")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-01-12', 'season-1']::text[]),
  (26, 'west-wing', 'On Lord Marbury''s advice, Bartlet offers India help building a computer industry, to be discussed later so that it does not look like a trade. He pairs it with a threat to seize Indian assets if its troops do not pull back within a day. (S1E12, "He Shall, from Time to Time...")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-01-12', 'season-1']::text[]),
  (27, 'west-wing', 'Toby talks the President out of saying in the State of the Union that the era of big government is over. (S1E12, "He Shall, from Time to Time...")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['toby', '2000-01-12', 'season-1']::text[]),
  (28, 'west-wing', 'A congressman offers to drop hearings into Leo''s past if the White House shelves its sex-education report until after the midterms. Josh and Sam take the deal, and the President agrees. (S1E13, "Take Out the Trash Day")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', 'sam', '2000-01-26', 'season-1']::text[]),
  (29, 'west-wing', 'After Sam fires the junior staffer who leaked his treatment records, Leo gives her the job back. (S1E13, "Take Out the Trash Day")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['leo', '2000-01-26', 'season-1']::text[]),
  (30, 'west-wing', 'The father of a murdered gay teenager criticises the President''s record on gay rights before the hate-crimes bill signing. C.J. objects when Mandy wants the family sent home, then tells the press they left on family business. (S1E13, "Take Out the Trash Day")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['cj', '2000-01-26', 'season-1']::text[]),
  (31, 'west-wing', 'Bartlet does not commute a federal death sentence, though he opposes the death penalty and spends the weekend looking for a way out. (S1E14, "Take This Sabbath Day")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-02-09', 'season-1']::text[]),
  (32, 'west-wing', 'With C.J. at the dentist, Josh takes the press briefing himself and jokes that the President has a secret plan to fight inflation. (S1E15, "Celestial Navigation")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', '2000-02-16', 'season-1']::text[]),
  (33, 'west-wing', 'Toby and Sam get the President''s Supreme Court nominee out of a Connecticut police cell quietly, and talk him out of making a public fight of his arrest. (S1E15, "Celestial Navigation")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['toby', 'sam', '2000-02-16', 'season-1']::text[]),
  (34, 'west-wing', 'Leo makes the Housing Secretary apologise for implying, at a hearing, that a Republican congressman and his party were racist. (S1E15, "Celestial Navigation")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['leo', '2000-02-16', 'season-1']::text[]),
  (35, 'west-wing', 'Hoynes will not cast the tie-breaking Senate vote for an ethanol tax credit he has always opposed. Sam proposes letting three senators vote no so that the bill loses, and the President agrees, sparing Hoynes. (S1E16, "20 Hours in L.A.")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['sam', 'bartlet', '2000-02-23', 'season-1']::text[]),
  (36, 'west-wing', 'Bartlet refuses to speak out against a bill banning gay people from the military that has no chance of passing, telling an angry donor that attacking it would only keep it alive. (S1E16, "20 Hours in L.A.")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-02-23', 'season-1']::text[]),
  (37, 'west-wing', 'A pollster tells Bartlet that leading the charge for a flag-burning amendment would sew up his re-election. Bartlet mocks the issue and puts the pitch off. (S1E16, "20 Hours in L.A.")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-02-23', 'season-1']::text[]),
  (38, 'west-wing', 'When the Fed chairman dies, Bartlet holds off a day on naming the expected successor, who once dated his wife. When her preference for the man leaks, he admits he was always going to name him. (S1E17, "The White House Pro-Am")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-03-22', 'season-1']::text[]),
  (39, 'west-wing', 'Abbey Bartlet gets a congresswoman to withdraw a child-labour amendment that would have sunk the President''s trade bill. (S1E17, "The White House Pro-Am")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['abbey', '2000-03-22', 'season-1']::text[]),
  (40, 'west-wing', 'A civil-rights nominee turns out to support slavery reparations. Josh is sent to argue it out with him, and the White House stands by the nomination. (S1E18, "Six Meetings Before Lunch")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', '2000-04-05', 'season-1']::text[]),
  (41, 'west-wing', 'C.J. stops the President from storming into the briefing room after a reporter confronts his daughter on campus. She warns him that it would turn a non-story into a big one. (S1E18, "Six Meetings Before Lunch")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['cj', '2000-04-05', 'season-1']::text[]),
  (42, 'west-wing', 'Leo tells the President he has been governing too cautiously, and tells the staff to start fighting for what they believe even if it costs them. (S1E19, "Let Bartlet Be Bartlet")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['leo', '2000-04-26', 'season-1']::text[]),
  (43, 'west-wing', 'Bartlet decides to name two campaign-finance reformers to the Federal Election Commission, breaking the custom that party leaders in Congress choose them. (S1E19, "Let Bartlet Be Bartlet")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-04-26', 'season-1']::text[]),
  (44, 'west-wing', 'When Senate Republicans threaten to retaliate for the FEC picks with bills the White House hates, Josh dares them to go ahead. (S1E20, "Mandatory Minimums")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['josh', '2000-05-03', 'season-1']::text[]),
  (45, 'west-wing', 'Leo warns a group of congressional aides that he knows their bosses'' relatives got light treatment on drug charges, to stop attacks on the President''s drug policy. (S1E20, "Mandatory Minimums")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['leo', '2000-05-03', 'season-1']::text[]),
  (46, 'west-wing', 'Bartlet approves a chain of ambassador moves so that he can send an FEC commissioner abroad and give reformers a majority on the commission. The chain also removes an ambassador caught in an affair. (S1E21, "Lies, Damn Lies and Statistics")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-05-10', 'season-1']::text[]),
  (47, 'west-wing', 'Bartlet asks a Republican senator who opposes him on almost everything else to be his partner on banning soft money. (S1E21, "Lies, Damn Lies and Statistics")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-05-10', 'season-1']::text[]),
  (48, 'west-wing', 'Against Toby''s advice, Sam goes to give Laurie a graduation present and is photographed with her. (S1E21, "Lies, Damn Lies and Statistics")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['sam', '2000-05-10', 'season-1']::text[]),
  (49, 'west-wing', 'When an American pilot is shot down in the Iraqi no-fly zone, Bartlet orders an immediate rescue mission. (S1E22, "What Kind of Day Has It Been")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['bartlet', '2000-05-17', 'season-1']::text[]),
  (50, 'west-wing', 'On Leo''s instruction, C.J. misleads the press about the rescue mission for the downed pilot, and later defends doing so to a reporter. (S1E22, "What Kind of Day Has It Been")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_1']::text[], array['cj', '2000-05-17', 'season-1']::text[]),
  (51, 'west-wing', 'While the President is under anaesthetic, Leo runs the crisis from the Situation Room. Nobody invoked the 25th Amendment, and the President signed no letter handing power to the Vice President. (S2E1–2, "In the Shadow of Two Gunmen")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['leo', '2000-10-04', 'season-2']::text[]),
  (52, 'west-wing', 'With the President under anaesthetic, Hoynes follows Leo''s advice to hold the military alert level where it is, against the National Security Adviser''s call to raise it. (S2E1–2, "In the Shadow of Two Gunmen")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['hoynes', '2000-10-04', 'season-2']::text[]),
  (53, 'west-wing', 'After the shooting, Toby drafts a plan to have the Attorney General list hate groups and force them to name their members and funders. The President talks him out of it. (S2E3, "The Midterms")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['toby', '2000-10-18', 'season-2']::text[]),
  (54, 'west-wing', 'Leo cuts off White House support for a congressional candidate Sam recruited, after reports about the man''s jury selection as a prosecutor and his all-white college fraternity. Sam protests. (S2E3, "The Midterms")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['leo', '2000-10-18', 'season-2']::text[]),
  (55, 'west-wing', 'At a White House reception, Bartlet publicly takes apart a talk-radio host for citing the Bible against homosexuality. (S2E3, "The Midterms")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2000-10-18', 'season-2']::text[]),
  (56, 'west-wing', 'Bartlet has Leo hire Ainsley Hayes, a young Republican lawyer who beat Sam in a TV debate, as associate White House counsel. (S2E4, "In This White House")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2000-10-25', 'season-2']::text[]),
  (57, 'west-wing', 'C.J. silences a retiring general who plans to attack the President on television by threatening to reveal that he wears a medal he did not earn. (S2E5, "And It''s Surely to Their Credit")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['cj', '2000-11-01', 'season-2']::text[]),
  (58, 'west-wing', 'Bartlet tells C.J. to let the general say what he likes. (S2E5, "And It''s Surely to Their Credit")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2000-11-01', 'season-2']::text[]),
  (59, 'west-wing', 'Sam fires two White House lawyers for sending the new Republican hire dead flowers with an abusive card. (S2E5, "And It''s Surely to Their Credit")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['sam', '2000-11-01', 'season-2']::text[]),
  (60, 'west-wing', 'C.J. deliberately leaks to a reporter that the President is considering a lame-duck session of the Senate. (S2E6, "The Lame Duck Congress")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['cj', '2000-11-08', 'season-2']::text[]),
  (61, 'west-wing', 'Bartlet decides not to call a lame-duck session to ratify the nuclear test-ban treaty with the votes of senators who have just lost their seats. (S2E6, "The Lame Duck Congress")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2000-11-08', 'season-2']::text[]),
  (62, 'west-wing', 'After the Navy boards a tanker suspected of smuggling oil in breach of UN sanctions, Bartlet wants to seize the ship and sell its cargo. He settles for holding it in port while the oil is tested, which means a fine at most. (S2E7, "The Portland Trip")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2000-11-15', 'season-2']::text[]),
  (63, 'west-wing', 'Bartlet wants to veto outright a bill banning recognition of same-sex marriage. On Josh''s advice he settles for a pocket veto, knowing the bill will come back. (S2E7, "The Portland Trip")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2000-11-15', 'season-2']::text[]),
  (64, 'west-wing', 'Toby pushes the recess appointment of Leo''s sister to an education post, to pick a fight over school prayer. (S2E8, "Shibboleth")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['toby', '2000-11-22', 'season-2']::text[]),
  (65, 'west-wing', 'Leo persuades his own sister to withdraw from the recess appointment. (S2E8, "Shibboleth")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['leo', '2000-11-22', 'season-2']::text[]),
  (66, 'west-wing', 'Bartlet neither grants nor refuses asylum to Chinese Christians found in a shipping container. He quietly arranges with California''s governor for them to slip out of custody, so that China can save face. (S2E8, "Shibboleth")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2000-11-22', 'season-2']::text[]),
  (67, 'west-wing', 'After NASA loses contact with its Mars probe, C.J. urges the President to go ahead with the live broadcast to schoolchildren anyway. (S2E9, "Galileo")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['cj', '2000-11-29', 'season-2']::text[]),
  (68, 'west-wing', 'Leo confronts the Russian ambassador with satellite evidence of a missile silo fire Russia is covering up, and offers American help. (S2E9, "Galileo")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['leo', '2000-11-29', 'season-2']::text[]),
  (69, 'west-wing', 'C.J. learns that a painting France gave the White House was taken from a Jewish collector during the war, and returns it to his daughter with an apology. (S2E10, "Noël")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['cj', '2000-12-20', 'season-2']::text[]),
  (70, 'west-wing', 'Leo orders Josh to see a trauma specialist. (S2E10, "Noël")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['leo', '2000-12-20', 'season-2']::text[]),
  (71, 'west-wing', 'In private talks with the Majority Leader''s chief of staff, Toby threatens to attach a minimum-wage rise to every bill unless it gets a straight vote. She has the remark put to the press. (S2E11, "The Leadership Breakfast")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['toby', '2001-01-10', 'season-2', 'why:Aides talk to each other like this all the time. It seems silly that this one time it could be leaked and sink anything.']::text[]),
  (72, 'west-wing', 'Toby agrees to hold the press conference after the leadership breakfast at the Capitol and not at the White House, over C.J.''s objection. (S2E11, "The Leadership Breakfast")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['toby', '2001-01-10', 'season-2']::text[]),
  (73, 'west-wing', 'With Leo''s approval, Toby slips a rebuke of environmentalists for not condemning eco-terrorism into a speech Sam wrote for an environmental group, without telling Sam. (S2E12, "The Drop-In")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['toby', '2001-01-24', 'season-2']::text[]),
  (74, 'west-wing', 'Leo keeps pressing the President to back national missile defence after another failed test. (S2E12, "The Drop-In")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['leo', '2001-01-24', 'season-2']::text[]),
  (75, 'west-wing', 'C.J. asks a comedian to pull out of hosting a dinner the President will attend, because of an old joke that embarrassed him. (S2E12, "The Drop-In")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['cj', '2001-01-24', 'season-2']::text[]),
  (76, 'west-wing', 'On the night of the State of the Union, Josh runs a poll to see whether to push a gun law in five swing Democratic districts. (S2E13, "Bartlet''s Third State of the Union")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['josh', '2001-02-07', 'season-2']::text[]),
  (77, 'west-wing', 'Bartlet orders special forces to rescue five DEA agents held by rebels in Colombia. The intelligence is wrong, a helicopter is shot down, and nine soldiers die. (S2E14, "The War at Home")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2001-02-14', 'season-2']::text[]),
  (78, 'west-wing', 'Bartlet lets Colombia''s president free a jailed drug lord in exchange for the five DEA hostages. (S2E14, "The War at Home")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2001-02-14', 'season-2', 'nathan-bad', 'why:Bad to give in to terrorists.']::text[]),
  (79, 'west-wing', 'Josh asks the Surgeon General to resign after she says marijuana is no more dangerous than alcohol or tobacco. She refuses. (S2E15, "Ellie")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['josh', '2001-02-21', 'season-2']::text[]),
  (80, 'west-wing', 'Bartlet keeps the Surgeon General in her job. (S2E15, "Ellie")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2001-02-21', 'season-2']::text[]),
  (81, 'west-wing', 'To launch the Social Security commission, Toby has C.J. announce that a liberal senator who has been attacking the White House has joined it, before anyone has asked him. (S2E15, "Ellie")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['toby', '2001-02-21', 'season-2']::text[]),
  (82, 'west-wing', 'Sam pushes for a pardon for a man convicted of spying for the Soviet Union, then drops it when the National Security Adviser shows him proof of guilt. (S2E16, "Somebody''s Going to Emergency, Somebody''s Going to Jail")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['sam', '2001-02-28', 'season-2']::text[]),
  (83, 'west-wing', 'Josh turns down Senator Stackhouse''s request to add autism funding to a health bill, saying the deal is closed. Stackhouse filibusters. (S2E17, "The Stackhouse Filibuster")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['josh', '2001-03-14', 'season-2']::text[]),
  (84, 'west-wing', 'Once Donna works out why Stackhouse is filibustering, Bartlet has friendly senators ask him long questions so that he can rest. (S2E17, "The Stackhouse Filibuster")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['bartlet', '2001-03-14', 'season-2']::text[]),
  (85, 'west-wing', 'Hoynes, long a friend of the oil industry, volunteers to answer an oil executive who blamed rising fuel prices on the President''s emissions rules, and says the companies are overcharging. (S2E17, "The Stackhouse Filibuster")', array['https://en.wikipedia.org/wiki/The_West_Wing_season_2']::text[], array['hoynes', '2001-03-14', 'season-2']::text[])
) as v(n, topic, text, sources, tags)
where not exists (select 1 from public.facts f where f.topic = v.topic and f.text = v.text);
